#!/usr/bin/env python3
"""Exact check: the Lie subalgebra of the central extension b^ = b + F_p z generated by e1=E12, e2=E23, e0=E31 t
has dimensions 3,3,2,3,3,2,... in heights < 3p and 3 (not 2) in height 3p.
b = n^+(sl3) + t sl3[t] over F_p, cocycle omega(X t^a, Y t^b) = a tr(XY) [a+b=p].
The generators satisfy the Serre relations (ad e_i)^2 e_j = 0 (checked), so the Serre Lie algebra L_p(A2~) has
dim >= 3 in degree 3p: Gabber-Kac fails mod p at weight p*delta for every prime p >= 3.
Usage: serre_center.py p [maxheight]"""
import sys, itertools
p = int(sys.argv[1]); H = int(sys.argv[2]) if len(sys.argv) > 2 else 3 * p + 1

def E(i, j):
    M = [[0]*3 for _ in range(3)]; M[i][j] = 1; return M

def mul(X, Y):
    return [[sum(X[i][k]*Y[k][j] for k in range(3)) % p for j in range(3)] for i in range(3)]

def br(u, v):
    # element: (dict t-power -> 3x3 matrix, central coefficient)
    out = {}; z = 0
    for a, X in u[0].items():
        for b, Y in v[0].items():
            XY, YX = mul(X, Y), mul(Y, X)
            C = [[(XY[i][j]-YX[i][j]) % p for j in range(3)] for i in range(3)]
            if any(any(r) for r in C):
                if a+b in out:
                    out[a+b] = [[(out[a+b][i][j]+C[i][j]) % p for j in range(3)] for i in range(3)]
                else:
                    out[a+b] = C
            if a + b == p:
                z = (z + a*sum(XY[i][i] for i in range(3))) % p
    z = (z + 0) % p
    return (out, z)

def vec(u):
    v = []
    for n in range(0, H//3 + 2):
        X = u[0].get(n, [[0]*3]*3)
        v += [X[i][j] for i in range(3) for j in range(3)]
    return v + [u[1]]

def rank_basis(elts):
    rows, basis, piv = [], [], []
    for e in elts:
        r = vec(e)
        for (pc, row) in zip(piv, rows):
            if r[pc]:
                f = r[pc]; r = [(x - f*y) % p for x, y in zip(r, row)]
        nz = [k for k, x in enumerate(r) if x]
        if nz:
            k = nz[0]; inv = pow(r[k], p-2, p); r = [(x*inv) % p for x in r]
            # reduce existing rows
            for idx in range(len(rows)):
                if rows[idx][k]:
                    f = rows[idx][k]; rows[idx] = [(x - f*y) % p for x, y in zip(rows[idx], r)]
            rows.append(r); piv.append(k); basis.append(e)
    return basis

gens = [({0: E(0, 1)}, 0), ({0: E(1, 2)}, 0), ({1: E(2, 0)}, 0)]
zero = lambda u: not u[1] and not any(any(any(r) for r in X) for X in u[0].values())
serre = all(zero(br(gens[i], br(gens[i], gens[j]))) for i in range(3) for j in range(3) if i != j)
print(f"p={p}: Serre relations (ad e_i)^2 e_j = 0 hold in b^: {serre}")
comp = {1: gens}
dims = [3]
for h in range(2, H+1):
    comp[h] = rank_basis([br(g, x) for g in gens for x in comp[h-1]])
    dims.append(len(comp[h]))
cz = [h for h in range(1, H+1) if any(u[1] for u in comp[h])]
print(f"p={p}: dims by height 1..{H}: {dims}")
print(f"p={p}: heights where the generated subalgebra meets the centre direction: {cz}")
